package com.bank.rebuild;

import java.util.HashMap;
import java.util.Map;
import java.util.logging.Logger;

// Rebuilds a binary tree from its preorder and inorder traversals.
public class TreeBuilderService {

    private static final Logger log = Logger.getLogger(TreeBuilderService.class.getName());

    private String[] preorder;
    private Map<String, Integer> inorderIndex;
    private int preIdx;

    public RoleNode buildTree(String[] preorder, String[] inorder) {
        this.preorder = preorder;
        this.preIdx = 0;
        this.inorderIndex = new HashMap<>();
        for (int i = 0; i < inorder.length; i++) {
            inorderIndex.put(inorder[i], i); // value → inorder position
        }
        RoleNode root = build(0, inorder.length - 1);
        log.info(() -> "Rebuilt hierarchy from " + preorder.length + " roles");
        return root;
    }

    // Build the subtree whose inorder range is [inLeft, inRight].
    private RoleNode build(int inLeft, int inRight) {
        if (inLeft > inRight) {
            return null; // empty range → no node
        }
        String rootValue = preorder[preIdx++]; // next root in preorder
        RoleNode node = new RoleNode(rootValue);
        int mid = inorderIndex.get(rootValue);  // split point in inorder

        // Build left BEFORE right (preorder = node, left, right).
        node.setLeft(build(inLeft, mid - 1));
        node.setRight(build(mid + 1, inRight));
        return node;
    }

    // Simple preorder stringification to verify the rebuild.
    public String preorderString(RoleNode node) {
        if (node == null) return "_";
        return node.getRole() + "(" + preorderString(node.getLeft())
                + "," + preorderString(node.getRight()) + ")";
    }
}
