package com.bank.rebuild;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class BuildTreeDemo {

    private static final Logger log = Logger.getLogger(BuildTreeDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Rebuild Hierarchy from Traversal Logs");

        // Target tree:        Manager
        //                    /        \
        //              CreditOfficer  RiskHead
        //                /      \
        //            Clerk    Verifier
        // Preorder (N,L,R): Manager, CreditOfficer, Clerk, Verifier, RiskHead
        // Inorder  (L,N,R): Clerk, CreditOfficer, Verifier, Manager, RiskHead
        String[] preorder = {"Manager", "CreditOfficer", "Clerk", "Verifier", "RiskHead"};
        String[] inorder  = {"Clerk", "CreditOfficer", "Verifier", "Manager", "RiskHead"};

        TreeBuilderService service = new TreeBuilderService();
        RoleNode root = service.buildTree(preorder, inorder);
        log.info("Rebuilt tree (preorder form): " + service.preorderString(root));
    }
}
